    Record = apps.get_model("controlled_vocabularies", "Record")
    Link = apps.get_model("controlled_vocabularies", "Link")
    db = schema_editor.connection.alias
    rows = []
    for record in (
        Record.objects.using(db).only("pk", "data").iterator(chunk_size=BATCH_SIZE)
    ):
        for predicate, entries in record.data.items():
            rows.extend(
                Link(source_id=record.pk, predicate=predicate, target=entry["@id"])
                for entry in entries
                if "@id" in entry
            )
        if len(rows) >= BATCH_SIZE:
            Link.objects.using(db).bulk_create(rows)
            rows = []
    Link.objects.using(db).bulk_create(rows)


